	@Test
	public void standaloneParserPreservesSuppliedValueFactoryCallbacks() throws IOException, RDFHandlerException {
		class CallbackIRI extends SimpleIRI {
			CallbackIRI(String iri) {
				super(iri);
			}
		}
		class CallbackLiteral extends SimpleLiteral {
			CallbackLiteral(String label, IRI datatype, CoreDatatype coreDatatype) {
				super(label, datatype, coreDatatype);
			}
		}
		class CallbackStatement extends GenericStatement<Resource, IRI, Value> {
			CallbackStatement(Resource subject, IRI predicate, Value object, Resource context) {
				super(subject, predicate, object, context);
			}
		}
		class CallbackTripleTerm extends SimpleTripleTerm {
			CallbackTripleTerm(Resource subject, IRI predicate, Value object) {
				super(subject, predicate, object);
			}
		}
		class CallbackValueFactory extends SimpleValueFactory {
			private int iriCalls;
			private int literalCalls;
			private int bnodeCalls;
			private int statementCalls;
			private int tripleTermCalls;

			@Override
			public IRI createIRI(String iri) {
				iriCalls++;
				return new CallbackIRI(iri);
			}

			@Override
			public Literal createLiteral(String label, IRI datatype, CoreDatatype coreDatatype) {
				literalCalls++;
				return new CallbackLiteral(label, datatype, coreDatatype);
			}

			@Override
			public BNode createBNode() {
				bnodeCalls++;
				return super.createBNode("factory-fresh-" + bnodeCalls);
			}

			@Override
			public Statement createStatement(Resource subject, IRI predicate, Value object, Resource context) {
				statementCalls++;
				return new CallbackStatement(subject, predicate, object, context);
			}

			@Override
			public TripleTerm createTripleTerm(Resource subject, IRI predicate, Value object) {
				tripleTermCalls++;
				return new CallbackTripleTerm(subject, predicate, object);
			}
		}

		CallbackValueFactory factory = new CallbackValueFactory();
		ArrayList<Statement> statements = new ArrayList<>();
		SPARQLUpdateDataBlockParser parser = new SPARQLUpdateDataBlockParser(factory);
		parser.setRDFHandler(new AbstractRDFHandler() {
			@Override
			public void handleStatement(Statement statement) {
				statements.add(statement);
			}
		});
		parser.parse(new StringReader("<urn:subject> <urn:predicate> \"literal\"^^<urn:datatype> . "
				+ "_:fresh <urn:predicate> <urn:object> . "
				+ "<urn:quoted> <urn:predicate> "
				+ "<<(<urn:quoted-subject> <urn:quoted-predicate> \"quoted\"^^<urn:datatype>)>> ."), "");

		assertEquals(3, statements.size());
		assertEquals(3, factory.statementCalls);
		assertEquals(2, factory.literalCalls);
		assertEquals(1, factory.bnodeCalls);
		assertEquals(1, factory.tripleTermCalls);
		assertNotEquals(0, factory.iriCalls);
		assertTrue(statements.get(0) instanceof CallbackStatement);
		assertTrue(statements.get(0).getSubject() instanceof CallbackIRI);
		assertTrue(statements.get(0).getPredicate() instanceof CallbackIRI);
		assertTrue(statements.get(0).getObject() instanceof CallbackLiteral);
		assertTrue(((Literal) statements.get(0).getObject()).getDatatype() instanceof CallbackIRI);
		assertEquals("factory-fresh-1", ((BNode) statements.get(1).getSubject()).getID());
		assertTrue(statements.get(1).getPredicate() instanceof CallbackIRI);
		assertTrue(statements.get(1).getObject() instanceof CallbackIRI);
		assertTrue(statements.get(2).getSubject() instanceof CallbackIRI);
		assertTrue(statements.get(2).getPredicate() instanceof CallbackIRI);
		TripleTerm quoted = assertInstanceOf(CallbackTripleTerm.class, statements.get(2).getObject());
		assertTrue(quoted.getSubject() instanceof CallbackIRI);
		assertTrue(quoted.getPredicate() instanceof CallbackIRI);
		assertTrue(quoted.getObject() instanceof CallbackLiteral);
	}

	@Test
	public void testParserConfigNormalizesDataBlockDatatypeValues() throws IOException, RDFHandlerException {
		ParserConfig config = new ParserConfig();
		config.set(BasicParserSettings.NORMALIZE_DATATYPE_VALUES, true);

		Literal literal = parseDataBlockLiteral(config,
				"<urn:s> <urn:p> \"+01\"^^<http://www.w3.org/2001/XMLSchema#integer> .");

		assertEquals("1", literal.getLabel());
		assertEquals("http://www.w3.org/2001/XMLSchema#integer", literal.getDatatype().stringValue());
	}

	@Test
	public void testParserConfigVerifiesValidAndInvalidDataBlockDatatypeValues() throws IOException,
			RDFHandlerException {
		ParserConfig config = new ParserConfig();
		config.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, true);

		Literal literal = parseDataBlockLiteral(config,
				"<urn:s> <urn:p> \"+01\"^^<http://www.w3.org/2001/XMLSchema#integer> .");
		assertEquals("+01", literal.getLabel());

		SPARQLUpdateDataBlockParser parser = new SPARQLUpdateDataBlockParser();
		parser.setParserConfig(config);
		parser.setRDFHandler(new StatementCollector());
		assertThrows(RDFParseException.class,
				() -> parser.parse(new StringReader(
						"<urn:s> <urn:p> \"not-an-integer\"^^<http://www.w3.org/2001/XMLSchema#integer> ."),
						"urn:base:"));
	}

	@Test
	public void testTopLevelPrefixAndBaseDirectivesRemainSequentialAcrossGraphBlocks()
			throws IOException, RDFParseException, RDFHandlerException {
		String dataBlock = "@prefix ex: <http://example.org/first#> .\n"
				+ "@base <http://example.org/base/first/> .\n"
				+ "<_:fixed> ex:p _:shared .\n"
				+ "GRAPH ex:firstGraph { <relative> ex:p _:shared . }\n"
				+ "@prefix ex: <http://example.org/second#> .\n"
				+ "@base <http://example.org/base/second/> .\n"
				+ "<_:fixed> ex:p _:shared .\n"
				+ "GRAPH ex:secondGraph { <relative> ex:p _:shared . }";
		SPARQLUpdateDataBlockParser parser = new SPARQLUpdateDataBlockParser();
		LinkedHashModel actual = new LinkedHashModel();
		parser.setRDFHandler(new StatementCollector(actual));
		parser.parse(new StringReader(dataBlock), "http://example.org/original/");

		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		BNode fixed = vf.createBNode("fixed");
		BNode shared = actual.stream()
				.map(Statement::getObject)
				.filter(BNode.class::isInstance)
				.map(BNode.class::cast)
				.findFirst()
				.orElseThrow();
		assertEquals(4, actual.size());
		assertNotEquals(fixed, shared, "ordinary DATA labels are fresh, even when their source label is stable");
		actual.forEach(statement -> assertEquals(shared, statement.getObject(),
				"one ordinary DATA label shares an identity across directive and graph scopes"));
		IRI firstPredicate = vf.createIRI("http://example.org/first#p");
		IRI secondPredicate = vf.createIRI("http://example.org/second#p");
		Model expected = new LinkedHashModel();
		expected.add(fixed, firstPredicate, shared);
		expected.add(vf.createIRI("http://example.org/base/first/relative"), firstPredicate, shared,
				vf.createIRI("http://example.org/first#firstGraph"));
		expected.add(fixed, secondPredicate, shared);
		expected.add(vf.createIRI("http://example.org/base/second/relative"), secondPredicate, shared,
				vf.createIRI("http://example.org/second#secondGraph"));

		assertEquals(Set.copyOf(expected), Set.copyOf(actual),
				"directives must affect only following terms; fixed references and ordinary blank labels keep their identities");
	}

	@Test
	public void testPrefixLocalEscapesUseSPARQLUnescapingAndPreservePercentSequences()
			throws Exception {
		String update = "PREFIX ex: <urn:escaped:> INSERT DATA { "
				+ "<urn:s> ex:a\\$b <urn:o> . <urn:s> ex:path%2Fsegment <urn:o> . }";
		ParsedUpdate parsed = new SPARQLParser().parseUpdate(update, "urn:base:");
		String dataBlock = ((InsertData) parsed.getUpdateExprs().get(0)).getDataBlock();
		SPARQLUpdateDataBlockParser parser = new SPARQLUpdateDataBlockParser();
		LinkedHashModel actual = new LinkedHashModel();
		parser.setRDFHandler(new StatementCollector(actual));
		parser.parse(new StringReader(dataBlock), "urn:base:");

		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		Model expected = new LinkedHashModel();
		expected.add(vf.createIRI("urn:s"), vf.createIRI("urn:escaped:a$b"), vf.createIRI("urn:o"));
		expected.add(vf.createIRI("urn:s"), vf.createIRI("urn:escaped:path%2Fsegment"), vf.createIRI("urn:o"));
		assertEquals(Set.copyOf(expected), Set.copyOf(actual));
	}

	private Literal parseDataBlockLiteral(ParserConfig config, String dataBlock)
			throws IOException, RDFParseException, RDFHandlerException {
		SPARQLUpdateDataBlockParser parser = new SPARQLUpdateDataBlockParser();
		parser.setParserConfig(config);
		StatementCollector statements = new StatementCollector();
		parser.setRDFHandler(statements);
		parser.parse(new StringReader(dataBlock), "urn:base:");
		return (Literal) statements.getStatements().iterator().next().getObject();
	}
